#!/bin/sh
# Name: Photo
# Author: photo-kit
# Icon: data:image/jpeg;base64,
# DontUseFBInk
# 电子相册: 顶部=设置 左/右=翻页 中间=退出
PV=/mnt/us/photo-kit/photoviewer
CONF=/mnt/us/photo-kit/photo.conf
INTERVAL=600
SLEEP=0
[ -f "$CONF" ] && . "$CONF"
[ -z "$INTERVAL" ] && INTERVAL=600

FW=$(cut -d' ' -f2 /mnt/us/system/version.txt 2>/dev/null)
UI_MODE=pillow
case "$FW" in
    5.1[3-9].*|5.[2-9].*|6.*) UI_MODE=framework ;;
esac

hide_ui() {
    lipc-set-prop -i com.lab126.powerd preventScreenSaver 1 2>/dev/null
    lipc-set-prop -i com.lab126.powerd touchScreenSaverTimeout 86400 2>/dev/null
    if [ "$UI_MODE" = pillow ]; then
        killall -STOP pillowd 2>/dev/null
    else
        stop framework 2>/dev/null
        stop lab126_gui 2>/dev/null
        stop pillow 2>/dev/null
        i=0
        while [ $i -lt 15 ]; do
            C=$(pidof cvm 2>/dev/null); W=$(pidof pillowd 2>/dev/null)
            [ -z "$C" ] && [ -z "$W" ] && break
            sleep 1
            i=$((i + 1))
            stop framework 2>/dev/null
            stop lab126_gui 2>/dev/null
            stop pillow 2>/dev/null
        done
    fi
}

show_ui() {
    if [ "$UI_MODE" = pillow ]; then
        killall -CONT pillowd 2>/dev/null
        lipc-set-prop com.lab126.pillow disableEnablePillow disable 2>/dev/null
        sleep 1
        lipc-set-prop com.lab126.pillow disableEnablePillow enable 2>/dev/null
    else
        start pillow 2>/dev/null
        start lab126_gui 2>/dev/null
        start framework 2>/dev/null
    fi
}

# 防重入: 已有实例在跑时不再起第二个(双实例会抢屏/抢输入);
# 此时不调 show_ui —— UI 抑制状态由正主会话管理, 它退出时会恢复
if pidof photoviewer >/dev/null 2>&1; then exit 0; fi
hide_ui
SFLAG=""
[ "$SLEEP" = "1" ] && SFLAG="-s"
"$PV" -a "$INTERVAL" $SFLAG /mnt/us/photo-kit/photos >>/mnt/us/photo-kit/viewer.log 2>&1
show_ui
